363	     */
364	    public Pet getPet(String name, boolean ignoreNew) {
365	        name = name.toLowerCase();
366	        for (Pet pet : getPetsInternal()) {
367	            if (!ignoreNew || !pet.isNew()) {
368	                String compName = pet.getName();
